"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["34373"],{91627(e){e.exports=JSON.parse('{"id":"V4-148","slug":"carbon-footprint","term":"Carbon Footprint","also_known_as":[],"difficulty":"Beginner","definition":"A carbon footprint is the total amount of greenhouse gases emitted directly and indirectly by a person, organisation, product, event or activity, usually expressed in tonnes of carbon dioxide equivalent.","explanation":["Greenhouse gases include carbon dioxide, methane, nitrous oxide and several others. Because these gases trap heat to different degrees, they are converted into carbon dioxide equivalent, often written as CO2e, so that they can be added together.","For organisations, a carbon footprint is typically measured using the Greenhouse Gas Protocol, which divides emissions into Scope 1, direct emissions; Scope 2, indirect emissions from purchased energy; and Scope 3, all other indirect emissions in the value chain.","For example, a company\u2019s carbon footprint would include emissions from its vehicles and boilers, from the electricity it buys and from producing the goods it buys and the use of the products it sells.","Measuring carbon footprints helps organisations understand where their emissions come from, set reduction targets and report their progress. Investors measure the carbon footprint of their portfolios, often expressed relative to the amount invested or revenues of the companies held. Carbon footprint calculations depend on estimates and assumptions, especially for indirect emissions, so results can vary between methods."],"note":"","total":1725,"prev":{"slug":"carbon-credit","term":"Carbon Credit"},"next":{"slug":"carbon-offset","term":"Carbon Offset"}}')}}]);